∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {G : SimpleGraph V} (P Q : Erdos1017.FractionalPartition G)
  (t : ℝ) (ht : 0 ≤ t) (ht1 : t ≤ 1),
  P.mix Q t ht ht1 = { mass := fun s => t * P.mass s + (1 - t) * Q.mass s, nonneg := ⋯, supported := ⋯, edge_load := ⋯ }

∀ {V : Type u_1} {inst : Fintype V} {inst_1 : DecidableEq V} {G : SimpleGraph V} {mass : Finset V → ℝ}
  {nonneg : ∀ (s : Finset V), 0 ≤ mass s} {supported : ∀ (s : Finset V), mass s ≠ 0 → G.IsClique ↑s ∧ 2 ≤ s.card}
  {edge_load : ∀ (u v : V), G.Adj u v → (∑ s, if u ∈ s ∧ v ∈ s then mass s else 0) = 1} {mass_1 : Finset V → ℝ}
  {nonneg_1 : ∀ (s : Finset V), 0 ≤ mass_1 s}
  {supported_1 : ∀ (s : Finset V), mass_1 s ≠ 0 → G.IsClique ↑s ∧ 2 ≤ s.card}
  {edge_load_1 : ∀ (u v : V), G.Adj u v → (∑ s, if u ∈ s ∧ v ∈ s then mass_1 s else 0) = 1},
  { mass := mass, nonneg := nonneg, supported := supported, edge_load := edge_load } =
      { mass := mass_1, nonneg := nonneg_1, supported := supported_1, edge_load := edge_load_1 } →
    mass = mass_1

