  {quota : ∀ (i : ι), x i * (∑ j, x j - a - x i) ≤ Erdos1017.subsetMoment mass {i}}
  {total : ∑ T, mass T ≤ (∑ i, x i - a) * ((∑ i, x i) ^ 2 - ∑ i, x i ^ 2) / (3 * ∑ i, x i)} {mass_1 : Finset ι → ℝ}
