  {total_1 : ∑ T, mass_1 T ≤ (∑ i, x i - a) * ((∑ i, x i) ^ 2 - ∑ i, x i ^ 2) / (3 * ∑ i, x i)},
  { mass := mass, supported := supported, nonneg := nonneg, pair_cap := pair_cap, quota := quota, total := total } =
